BEGIN READ ONLY;
SET LOCAL statement_timeout='30s'; SET LOCAL lock_timeout='3s'; SET LOCAL jit=off; SET LOCAL enable_nestloop=off;
WITH members AS MATERIALIZED(SELECT DISTINCT m.con_code AS ts_code FROM core_serving.dc_member m JOIN core_serving.dc_index i ON i.trade_date=m.trade_date AND i.ts_code=m.ts_code WHERE m.trade_date=DATE '2026-09-30' AND i.idx_type='行业板块' AND i.level='东财一级行业'),
base AS MATERIALIZED(SELECT m.ts_code FROM members m JOIN raw_tushare.stock_basic s ON s.ts_code=m.ts_code WHERE s.ts_code !~ '^(200|900)' AND s.list_date<=DATE '2026-09-30' AND (s.delist_date IS NULL OR s.delist_date>DATE '2026-09-30')),
i AS MATERIALIZED(SELECT ts_code,end_date,CASE WHEN comp_type='1' THEN revenue IS NOT NULL ELSE total_revenue IS NOT NULL END r_ok,n_income_attr_p IS NOT NULL p_ok FROM core_serving.equity_income WHERE end_date IN (DATE '2019-09-30',DATE '2019-12-31',DATE '2020-09-30',DATE '2020-12-31',DATE '2021-09-30',DATE '2021-12-31',DATE '2022-09-30',DATE '2022-12-31',DATE '2023-09-30',DATE '2023-12-31',DATE '2024-09-30',DATE '2024-12-31',DATE '2025-09-30',DATE '2025-12-31')),
c AS MATERIALIZED(SELECT ts_code,end_date,n_cashflow_act IS NOT NULL c_ok FROM core_serving.equity_cashflow WHERE end_date IN (DATE '2019-09-30',DATE '2019-12-31',DATE '2020-09-30',DATE '2020-12-31',DATE '2021-09-30',DATE '2021-12-31',DATE '2022-09-30',DATE '2022-12-31',DATE '2023-09-30',DATE '2023-12-31',DATE '2024-09-30',DATE '2024-12-31',DATE '2025-09-30',DATE '2025-12-31')),
f AS MATERIALIZED(SELECT DISTINCT ON(ts_code,end_date) ts_code,end_date,profit_dedt IS NOT NULL d_ok FROM raw_tushare.fina_indicator WHERE end_date IN (DATE '2019-09-30',DATE '2019-12-31',DATE '2020-09-30',DATE '2020-12-31',DATE '2021-09-30',DATE '2021-12-31',DATE '2022-09-30',DATE '2022-12-31',DATE '2023-09-30',DATE '2023-12-31',DATE '2024-09-30',DATE '2024-12-31',DATE '2025-09-30',DATE '2025-12-31') ORDER BY ts_code,end_date,CASE update_flag WHEN '1' THEN 0 ELSE 1 END,ann_date DESC,fetched_at DESC,source_content_hash DESC),
years AS(SELECT generate_series(2019,2025) y),
pairs AS MATERIALIZED(SELECT b.ts_code,y.y,coalesce(i9.r_ok AND i12.r_ok,false) revenue_pair,coalesce(i9.p_ok AND i12.p_ok,false) parent_profit_pair,coalesce(c9.c_ok AND c12.c_ok,false) ocf_pair,coalesce(f9.d_ok AND f12.d_ok,false) deducted_profit_pair FROM base b CROSS JOIN years y LEFT JOIN i i9 ON i9.ts_code=b.ts_code AND i9.end_date=make_date(y.y,9,30) LEFT JOIN i i12 ON i12.ts_code=b.ts_code AND i12.end_date=make_date(y.y,12,31) LEFT JOIN c c9 ON c9.ts_code=b.ts_code AND c9.end_date=make_date(y.y,9,30) LEFT JOIN c c12 ON c12.ts_code=b.ts_code AND c12.end_date=make_date(y.y,12,31) LEFT JOIN f f9 ON f9.ts_code=b.ts_code AND f9.end_date=make_date(y.y,9,30) LEFT JOIN f f12 ON f12.ts_code=b.ts_code AND f12.end_date=make_date(y.y,12,31)),
q AS(SELECT y,count(*) cohort_codes,count(*) FILTER(WHERE revenue_pair) revenue_q4_codes,count(*) FILTER(WHERE parent_profit_pair) parent_profit_q4_codes,count(*) FILTER(WHERE ocf_pair) ocf_q4_codes,count(*) FILTER(WHERE revenue_pair AND parent_profit_pair AND ocf_pair) three_metrics_q4_codes,count(*) FILTER(WHERE deducted_profit_pair) deducted_q4_codes FROM pairs GROUP BY y),
h AS(SELECT ts_code,count(*) FILTER(WHERE revenue_pair) r_years,count(*) FILTER(WHERE parent_profit_pair) p_years,count(*) FILTER(WHERE ocf_pair) c_years,count(*) FILTER(WHERE deducted_profit_pair) d_years,count(*) FILTER(WHERE y>=2023 AND revenue_pair AND parent_profit_pair AND ocf_pair) recent3 FROM pairs GROUP BY ts_code),
hist AS(SELECT r_years,p_years,c_years,d_years,count(*) codes FROM h GROUP BY r_years,p_years,c_years,d_years)
SELECT jsonb_build_object('section','q4_cohort_history','as_of',current_timestamp,'cohort_codes',(SELECT count(*) FROM base),'year_counts',(SELECT jsonb_agg(to_jsonb(q) ORDER BY y) FROM q),'history_histogram',(SELECT jsonb_agg(to_jsonb(hist) ORDER BY r_years,p_years,c_years,d_years) FROM hist),'recent_three_metrics_3years',(SELECT count(*) FROM h WHERE recent3=3));
COMMIT;
BEGIN READ ONLY;
SET LOCAL statement_timeout='30s'; SET LOCAL lock_timeout='3s'; SET LOCAL jit=off; SET LOCAL enable_nestloop=off;
WITH members AS MATERIALIZED(SELECT DISTINCT m.con_code AS ts_code FROM core_serving.dc_member m JOIN core_serving.dc_index i ON i.trade_date=m.trade_date AND i.ts_code=m.ts_code WHERE m.trade_date=DATE '2026-09-30' AND i.idx_type='行业板块' AND i.level='东财一级行业'),
base AS MATERIALIZED(SELECT m.ts_code FROM members m JOIN raw_tushare.stock_basic s ON s.ts_code=m.ts_code WHERE s.ts_code !~ '^(200|900)' AND s.list_date<=DATE '2026-09-30' AND (s.delist_date IS NULL OR s.delist_date>DATE '2026-09-30')),
i AS MATERIALIZED(SELECT ts_code,revenue,n_income_attr_p,comp_type FROM core_serving.equity_income WHERE end_date=DATE '2026-09-30'),
f AS MATERIALIZED(SELECT DISTINCT ON(ts_code) ts_code,profit_dedt FROM raw_tushare.fina_indicator WHERE end_date=DATE '2026-09-30' ORDER BY ts_code,CASE update_flag WHEN '1' THEN 0 ELSE 1 END,ann_date DESC,fetched_at DESC,source_content_hash DESC),
b AS MATERIALIZED(SELECT ts_code,total_assets FROM core_serving.equity_balancesheet WHERE end_date=DATE '2026-09-30'),
c AS MATERIALIZED(SELECT ts_code,n_cashflow_act FROM core_serving.equity_cashflow WHERE end_date=DATE '2026-09-30'),
v AS MATERIALIZED(SELECT ts_code,total_mv,close,pb,pe_ttm,total_share,dv_ttm FROM core_serving.equity_daily_basic WHERE trade_date=DATE '2026-10-30'),
q AS(SELECT count(*) cohort_codes,count(i.ts_code) income_records,count(b.ts_code) balancesheet_records,count(c.ts_code) cashflow_records,count(f.ts_code) indicator_records,count(f.profit_dedt) deducted_nonnull,count(v.ts_code) valuation_records,count(*) FILTER(WHERE v.ts_code IS NULL) missing_valuation,count(*) FILTER(WHERE v.total_mv>0 AND v.close>0 AND v.total_share>0) basic_valuation_valid,count(v.pe_ttm) pe_nonnull,count(v.pb) pb_nonnull,count(v.dv_ttm) dv_nonnull,count(*) FILTER(WHERE v.total_mv>0 AND i.n_income_attr_p IS NOT NULL) forecast_pe_inputs,count(*) FILTER(WHERE v.total_mv>0 AND i.ts_code IS NOT NULL AND b.ts_code IS NOT NULL AND c.ts_code IS NOT NULL) three_statements_and_valuation,count(*) FILTER(WHERE i.ts_code IS NOT NULL AND b.ts_code IS NOT NULL AND c.ts_code IS NOT NULL AND f.profit_dedt IS NOT NULL) three_statements_and_deducted FROM base a LEFT JOIN i ON i.ts_code=a.ts_code LEFT JOIN b ON b.ts_code=a.ts_code LEFT JOIN c ON c.ts_code=a.ts_code LEFT JOIN f ON f.ts_code=a.ts_code LEFT JOIN v ON v.ts_code=a.ts_code)
SELECT jsonb_build_object('section','current_cohort_coverage','as_of',current_timestamp,'data',to_jsonb(q)) FROM q;
COMMIT;
